    "jsHint": "JS는 Vue 컴포넌트의 setup 반환값으로 객체를 return해야 합니다. 백엔드 API 호출에는 ctx.api.get('/me')를 사용하세요. 저장 후 포털 페이지에 접속하면 실제 결과를 확인할 수 있습니다.",
    "ctxApiRefBody": "ctx.ref(val)              — 반응형 변수 생성\nctx.computed(fn)          — 계산된 속성 생성\nctx.watch(src, cb)        — 변경 사항 감시\nctx.onMounted(fn)         — 컴포넌트 마운트 시\nctx.onUnmounted(fn)       — 컴포넌트 언마운트 시\n\nctx.data.client           — 사용자 계정 정보 (반응형)\nctx.data.token            — 현재 token (반응형)\nctx.data.isDark           — 다크 모드 (반응형)\n\nctx.api.get(path, query)  — GET 요청\nctx.api.post(path, body)  — POST 요청\nctx.api.put(path, body)   — PUT 요청\nctx.api.delete(path)      — DELETE 요청\n\nctx.formatBytes(bytes)    — 파일 크기 포맷\nctx.formatDate(date)      — 날짜 포맷\nctx.copyText(text)        — 클립보드에 복사\nctx.elMessage             — Element Plus 메시지 알림\nctx.config                — 포털 구성 (PORTAL_CONFIG)\nctx.moduleId              — 현재 모듈 ID\nctx.moduleTitle           — 현재 모듈 제목",
